import{_ as a,o as t,c as r,a5 as o}from"./chunks/framework.CcrBcQWS.js";const g=JSON.parse('{"title":"Fire and Heat Precautions","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/safety/fire-and-heat-precautions.md","filePath":"manual/safety/fire-and-heat-precautions.md","lastUpdated":1787021357000}'),n={name:"manual/safety/fire-and-heat-precautions.md"};function s(i,e,l,c,d,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="fire-and-heat-precautions" tabindex="-1">Fire and Heat Precautions <a class="header-anchor" href="#fire-and-heat-precautions" aria-label="Permalink to &quot;Fire and Heat Precautions&quot;">​</a></h1><p>Measures to prevent fire, burns, and overheating when using the RBQ, charger, and battery.</p><h2 id="heat-and-contact" tabindex="-1">Heat and contact <a class="header-anchor" href="#heat-and-contact" aria-label="Permalink to &quot;Heat and contact&quot;">​</a></h2><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>1) The robot body and controller get hot after long use. Do not touch during operation or immediately after. Allow at least about 1 hour to cool, check UI temperature, or power off and let it cool.<br>2) Batteries, chargers, and docking stations can also get hot-do not place flammable material near them while charging.</p></div></div><ul><li><strong>Ventilation</strong>: Place the controller and charger in a well-ventilated area; do not cover with cloths or covers. Overheating can cause failure or fire.</li></ul><h2 id="fire-prevention" tabindex="-1">Fire prevention <a class="header-anchor" href="#fire-prevention" aria-label="Permalink to &quot;Fire prevention&quot;">​</a></h2><ul><li><strong>Flammables</strong>: Do not place paper, cloth, solvents, or other flammables near the robot or charger.</li><li><strong>Battery</strong>: Do not expose the battery to fire, crush it, or puncture it. Do not use a damaged battery; dispose of it safely.</li><li><strong>Charging</strong>: Use only the designated charger; do not use damaged cables or chargers. See also <a href="/RBQ/nightly/manual/safety/battery-handling.html">Battery Handling Precautions</a>.</li></ul><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><ul><li><strong>Smoke or odor</strong>: Turn power off immediately, unplug, and <strong>move to a safe distance</strong>.</li></ul><div class="sb sb-danger"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">DANGER</p><p><strong>If a fire starts</strong> on the RBQ, charger, or battery, <strong>do not attempt to extinguish it yourself.</strong> Prioritize life safety: <strong>evacuate</strong>, then call the fire service. Lithium batteries are hard to fully extinguish with water or ordinary extinguishers and may worsen the situation-use extinguishers suitable for electrical fires (gas, powder, etc.) as recommended.</p></div></div><ul><li><strong>Overheat alarm</strong>: If the product or GUI shows an overheat warning, stop use, let it cool, then consult the manual or Rainbow Robotics.</li></ul>',11)])])}const f=a(n,[["render",s]]);export{g as __pageData,f as default};
